class Flamingo_Inbound_Message
{
	...
    public function save()
	    {
			...
			update_post_meta($post_id, &#039;_subject&#039;, $this-&gt;subject);
			update_post_meta($post_id, &#039;_from&#039;, $this-&gt;from);
			update_post_meta($post_id, &#039;_from_name&#039;, $this-&gt;from_name);
			update_post_meta($post_id, &#039;_from_email&#039;, $this-&gt;from_email);

			// BEGIN EDITS TO THE ORIGINAL PLUGIN

			// Connect to your external database
			$external_db = new wpdb(
				EXTERNAL_DB_USER,
				EXTERNAL_DB_PASSWORD,
				EXTERNAL_DB_NAME,
				EXTERNAL_DB_HOST
			);

			// Check for database connection error
			if ($external_db-&gt;last_error) {
				error_log(&#039;Database connection error: &#039; . $external_db-&gt;last_error);
			}

			// Get the data fields from wp-config.php
			$fields_to_store = unserialize(EXTERNAL_DB_FIELDS);
			$constants_to_store = unserialize(EXTERNAL_DB_CONSTANTS);

			// Log the fields to store
			error_log(&#039;Fields to store: &#039; . print_r($fields_to_store, true));
			error_log(&#039;Constants to store: &#039; . print_r($constants_to_store, true));

			// Log the contents of $this-&gt;fields
			error_log(&#039;Contents of $this-&gt;fields: &#039; . print_r($this-&gt;fields, true));

			// Prepare data to insert
			foreach ($fields_to_store as $table =&gt; $fields) {
				$data = array();
				$found_fields = array(); // debugging
				$skipped_fields = array(); // debugging

				foreach ($fields as $db_field =&gt; $message_field) {
					if (is_array($message_field)) {
						// Handle multiple contact-field-values for one database-table-key
						$combined_value = array();
						foreach ($message_field as $field) {
							if (property_exists($this, $field)) {
								$combined_value[] = $this-&gt;$field;
							} elseif (isset($this-&gt;fields[$field])) {
								$combined_value[] = $this-&gt;fields[$field];
							}
						}
						$data[$db_field] = implode(&#039;/&#039;, $combined_value); // Pre-dominantly used for pronouns
						$found_fields[] = implode(&#039;, &#039;, $message_field);
						error_log(&quot;Set \$data[&#039;$db_field&#039;] to combined value: &quot; . print_r($data[$db_field], true));
					} elseif (property_exists($this, $message_field)) {
						// Field is a property of the class (e.g., from_name, from_email, subject)
						$data[$db_field] = $this-&gt;$message_field;
						$found_fields[] = $message_field;
						error_log(&quot;Set \$data[&#039;$db_field&#039;] to property \$$message_field: &quot; . print_r($data[$db_field], true));
					} elseif (isset($this-&gt;fields[$message_field])) {
						// Field is in the form fields (e.g., your-message)
						$data[$db_field] = $this-&gt;fields[$message_field];
						$found_fields[] = $message_field;
						error_log(&quot;Set \$data[&#039;$db_field&#039;] to \$this-&gt;fields[&#039;$message_field&#039;]: &quot; . print_r($data[$db_field], true));
					} elseif ($message_field === &#039;date&#039;) {
						// Special case for date
						$data[$db_field] = current_time(&#039;mysql&#039;);
						$found_fields[] = $message_field;
						error_log(&quot;Set \$data[&#039;$db_field&#039;] to current time: &quot; . $data[$db_field]);
					} else {
						// Handle missing fields
						$skipped_fields[] = $message_field;
						//// error_log(&quot;Field &#039;$message_field&#039; not found - skipping.&quot;);
					}
				}

				// Check if there are any constants to be inserted
				if (!empty($found_fields) &amp;&amp; isset($constants_to_store[$table])) {
					foreach ($constants_to_store[$table] as $db_field =&gt; $constant_value) {
						$data[$db_field] = $constant_value;
						error_log(&quot;Set \$data[&#039;$db_field&#039;] to constant value: &quot; . print_r($data[$db_field], true));
					}
				}

				// Insert data into your external database only if fields are found
				if (!empty($found_fields)) {
					error_log(&quot;Summary: Found &quot; . count($found_fields) . &quot; fields, Skipped &quot; . count($skipped_fields) . &quot; fields.&quot;);
					$result = $external_db-&gt;insert($table, $data);

					// Check for insert error
					if (false === $result) {
						error_log(&quot;Data insert error into &quot; . EXTERNAL_DB_NAME . &quot;, $table. Error: &quot; . $external_db-&gt;last_error);
					} else {
						error_log(&quot;Successfully stored into &quot; . EXTERNAL_DB_NAME . &quot;, $table.&quot;);
					}
				} else {
					error_log(&quot;No fields found to insert into the database for table: $table&quot;);
				}
			}

			// END EDITS TO THE ORIGINAL PLUGIN

			// THIS BIT NULLIFIES EVERYTHING
			foreach ($this-&gt;fields as $key =&gt; $value) {
				$meta_key = sanitize_key(&#039;_field_&#039; . $key);
				update_post_meta($post_id, $meta_key, $value);
				$this-&gt;fields[$key] = null;
			}

			update_post_meta($post_id, &#039;_fields&#039;, $this-&gt;fields);
			update_post_meta($post_id, &#039;_meta&#039;, $this-&gt;meta);
			update_post_meta($post_id, &#039;_akismet&#039;, $this-&gt;akismet);
			update_post_meta($post_id, &#039;_recaptcha&#039;, $this-&gt;recaptcha);
			update_post_meta($post_id, &#039;_spam_log&#039;, $this-&gt;spam_log);
			update_post_meta($post_id, &#039;_consent&#039;, $this-&gt;consent);
			update_post_meta($post_id, &#039;_hash&#039;, $this-&gt;hash);

			if (term_exists($this-&gt;channel, self::channel_taxonomy)) {
				wp_set_object_terms(
					$this-&gt;id,
					$this-&gt;channel,
					self::channel_taxonomy
				);
			}
		}

		return $post_id;
	}
...
}

